<script setup lang="ts">
import { computed, shallowRef } from 'vue'
import { Head, Link, useForm, usePage } from '@inertiajs/vue3'
import AppShell from '../../Components/AppShell.vue'
import PageHeader from '../../Components/PageHeader.vue'
import StatusBadge from '../../Components/StatusBadge.vue'
import DataState from '../../Components/DataState.vue'
import ConfirmModal from '../../Components/ConfirmModal.vue'
import { ArrowDownTrayIcon, ArrowPathIcon, LinkIcon, XCircleIcon } from '@heroicons/vue/24/outline'
import { formatDateTimeBR } from '../../utils/dateDisplay'
type LinkPayload = { active?: boolean; legacy?: boolean; status?: string; url?: string | null; actions?: { resend?: string | null; revoke?: string | null } }
const props = withDefaults(defineProps<{ quote: any; versions?: any[]; events?: any[]; attachments?: any[]; link?: LinkPayload | null }>(), { versions: () => [], events: () => [], attachments: () => [], link: null })
const page = usePage<{ flash?: { success?: string } }>()
const revokeForm = useForm({}); const resendForm = useForm({}); const linkForm = useForm({})
const confirmation = shallowRef<'revoke' | 'resend' | null>(null)
const copyState = shallowRef<'idle' | 'copied' | 'error'>('idle'); const actionStatus = shallowRef('')
const resendError = shallowRef(''); const revokeError = shallowRef(''); const failedAction = shallowRef<'resend' | 'revoke' | null>(null)
const realUrl = computed(() => props.link?.url || null)
const canEmail = computed(() => Boolean(props.quote.client?.email?.trim()))
const resendUrl = computed(() => props.link?.actions?.resend || null); const revokeUrl = computed(() => props.link?.actions?.revoke || null)
const errorMessage = computed(() => resendError.value || revokeError.value || Object.values(linkForm.errors)[0] || null)
const eventLabels: Record<string, string> = { sent: 'Enviado por e-mail', resent: 'Reenviado por e-mail', viewed: 'Visualizado', approved: 'Aprovado', rejected: 'Recusado' }
const eventLabel = (event: string) => eventLabels[event] || event
const dateTime = (value?: string | null) => formatDateTimeBR(value)
function revoke() { if (revokeUrl.value) confirmation.value = 'revoke' }
function resend() { if (resendUrl.value && canEmail.value) confirmation.value = 'resend' }
function confirmAction() {
  const action = confirmation.value; confirmation.value = null
  if (action === 'revoke' && revokeUrl.value) { revokeError.value = ''; failedAction.value = null; actionStatus.value = 'Revogando link…'; revokeForm.post(revokeUrl.value, { preserveScroll: true, onSuccess: () => { actionStatus.value = 'Link revogado.'; copyState.value = 'idle' }, onError: () => { revokeError.value = Object.values(revokeForm.errors)[0] || 'Não foi possível revogar o link.'; failedAction.value = 'revoke'; actionStatus.value = '' } }) }
  if (action === 'resend' && resendUrl.value) { resendError.value = ''; failedAction.value = null; actionStatus.value = 'Reenviando orçamento…'; resendForm.post(resendUrl.value, { preserveScroll: true, onSuccess: () => { actionStatus.value = 'Orçamento reenviado por e-mail.' }, onError: () => { resendError.value = Object.values(resendForm.errors)[0] || 'Não foi possível reenviar o orçamento.'; failedAction.value = 'resend'; actionStatus.value = '' } }) }
}
function retryAction() { if (failedAction.value === 'resend') resend(); else if (failedAction.value === 'revoke') revoke(); else if (Object.values(linkForm.errors).length) createLink() }
function createLink() { if (!linkForm.processing) linkForm.post(`/quotes/${props.quote.id}/public-link`, { preserveScroll: true }) }
async function copyLink() { if (!realUrl.value) return; try { await navigator.clipboard.writeText(realUrl.value); copyState.value = 'copied' } catch { copyState.value = 'error' } }
</script>
<template>
  <AppShell title="Versões e link" active="quotes">
    <Head title="Versões e link" />
    <div class="page-content min-w-0 space-y-6 p-4 sm:p-6 2xl:p-11">
      <PageHeader :title="`Versões e link · ${props.quote?.display_number || 'Orçamento'}`" description="Consulte o histórico e gerencie o acesso público." :back-href="`/quotes/${props.quote.id}`" back-label="Visualizar orçamento"><template #actions><a class="inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm font-medium text-td-ink hover:text-td-primary" :href="`/quotes/${props.quote.id}/download`"><ArrowDownTrayIcon class="size-5 shrink-0" aria-hidden="true" /> Baixar PDF</a></template></PageHeader>
      <p v-if="actionStatus" class="status-message rounded-lg border border-td-green/25 bg-td-green/5 px-4 py-3 text-sm leading-5 text-td-green-ink" role="status" aria-live="polite">{{ actionStatus }}</p>
      <p v-if="page.props.flash?.success" class="status-message rounded-lg border border-td-green/25 bg-td-green/5 px-4 py-3 text-sm leading-5 text-td-green-ink" role="status" aria-live="polite">{{ page.props.flash.success }}</p>
      <p v-if="errorMessage" class="error-summary rounded-lg border border-td-red/30 bg-td-red/5 px-4 py-3 text-sm leading-5 text-td-red" role="alert">{{ errorMessage }} <button class="btn-text inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-2 py-2 text-sm font-medium leading-5 text-td-primary hover:bg-td-primary/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" @click="retryAction">Tentar novamente</button></p>
      <div class="two-col grid min-w-0 grid-cols-1 items-start gap-6 xl:grid-cols-[minmax(0,2fr)_minmax(280px,1fr)]">
        <aside class="xl:col-start-2 xl:row-start-1 stack flex min-w-0 flex-col gap-6 [&>.field-label]:mb-[-12px]">
          <section class="panel min-w-0 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm shadow-td-card sm:p-6 [&_h2]:text-lg [&_h2]:font-semibold [&_h2]:leading-7 [&_h2]:text-td-ink flex flex-col gap-6 [&>.field-label]:mb-[-12px]"><div class="panel-heading flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-center [&_p]:mt-1 [&_p]:text-sm [&_p]:leading-5 [&_p]:text-td-body"><div><h2>Link público</h2><p>Compartilhe o acesso apenas com quem receber o link.</p></div><StatusBadge :value="props.link?.status || 'expired'" /></div><p class="form-help block text-sm leading-5 text-td-body">{{ realUrl ? 'Link ativo e disponível para copiar.' : props.link?.legacy ? 'Este link antigo não pode ser recuperado para cópia. Gerar outro desativará o anterior.' : 'Nenhum link ativo.' }}</p><div class="form-actions flex flex-col flex-wrap gap-3 sm:flex-row sm:items-center"><button v-if="!realUrl" class="btn-primary inline-flex min-h-11 items-center justify-center rounded-lg bg-td-primary px-4 py-2.5 text-sm font-medium text-white disabled:opacity-50" type="button" :disabled="linkForm.processing" @click="createLink">{{ linkForm.processing ? 'Criando…' : props.link?.legacy ? 'Gerar novo link' : 'Gerar link público' }}</button><button v-else class="btn-primary inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-center text-sm font-medium leading-5 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none [&_svg]:size-5 [&_svg]:shrink-0 border border-td-primary bg-td-primary text-white hover:bg-td-primary/90" type="button" :disabled="!realUrl" @click="copyLink"><LinkIcon class="size-5 shrink-0" aria-hidden="true" /> {{ copyState === 'copied' ? 'Copiar novamente' : 'Copiar link' }}</button><button v-if="revokeUrl && (realUrl || props.link?.legacy)" class="btn-secondary inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-center text-sm font-medium leading-5 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none [&_svg]:size-5 [&_svg]:shrink-0 border border-td-border bg-white text-td-ink hover:border-td-primary hover:text-td-primary" type="button" :disabled="revokeForm.processing" @click="revoke"><XCircleIcon class="size-5 shrink-0" aria-hidden="true" /> {{ revokeForm.processing ? 'Revogando…' : 'Revogar link' }}</button><button v-if="resendUrl && canEmail && ['draft', 'sent', 'viewed'].includes(props.quote.status)" class="btn-text inline-flex min-h-11 max-w-full items-center justify-center gap-2 rounded-lg px-2 py-2 text-sm font-medium leading-5 text-td-primary hover:bg-td-primary/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" :disabled="resendForm.processing" @click="resend"><ArrowPathIcon class="size-5 shrink-0" aria-hidden="true" /> {{ resendForm.processing ? 'Reenviando…' : 'Reenviar por e-mail' }}</button></div><p v-if="copyState === 'error'" class="error-summary rounded-lg border border-td-red/30 bg-td-red/5 px-4 py-3 text-sm leading-5 text-td-red" role="alert">Não foi possível copiar o link.</p><p v-if="copyState === 'copied'" class="text-sm text-td-green-ink" role="status">Link copiado. Você pode copiá-lo novamente.</p></section>
          <section class="rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm sm:p-6"><h2 class="text-lg font-semibold text-td-ink">Arquivos do orçamento</h2><p class="mt-2 text-sm text-td-body">{{ props.attachments.length }} {{ props.attachments.length === 1 ? 'arquivo anexado' : 'arquivos anexados' }}</p><Link class="mt-3 inline-flex min-h-11 items-center text-sm font-medium text-td-primary hover:underline" :href="`/quotes/${props.quote.id}#quote-attachments`">Ver e anexar arquivos</Link></section>
        </aside>
        <main class="xl:col-start-1 xl:row-start-1 stack flex min-w-0 flex-col gap-6 [&>.field-label]:mb-[-12px]">
          <section class="panel min-w-0 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm shadow-td-card sm:p-6 [&_h2]:text-lg [&_h2]:font-semibold [&_h2]:leading-7 [&_h2]:text-td-ink flex flex-col gap-6 [&>.field-label]:mb-[-12px]"><div class="panel-heading flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-center [&_p]:mt-1 [&_p]:text-sm [&_p]:leading-5 [&_p]:text-td-body"><div><h2>Versões</h2><p>Cada versão preserva os valores no momento do envio.</p></div></div><DataState v-if="!props.versions.length" kind="empty" title="Nenhuma versão registrada" /><div v-else class="stack flex min-w-0 flex-col gap-6 [&>.field-label]:mb-[-12px]"><article v-for="version in props.versions" :key="version.id" class="record-card group flex min-w-0 flex-col gap-4 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm [&_h3]:text-base [&_h3]:font-semibold [&_h3]:leading-6 [&_h3]:text-td-ink [&_dl]:grid [&_dl]:grid-cols-2 [&_dl]:gap-4 [&_dt]:text-sm [&_dt]:text-td-body [&_dd]:mt-1 [&_dd]:font-medium [&_dd]:text-td-ink"><div class="record-card__top flex min-w-0 flex-wrap items-start justify-between gap-3 [&>div]:min-w-0 [&_span]:text-sm [&_span]:leading-5"><h3>Versão {{ version.version }}</h3><strong class="text-sm tabular-nums text-td-ink">R$ {{ (version.total_cents / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2 }) }}</strong></div><p class="form-help block text-sm leading-5 text-td-body">{{ dateTime(version.created_at) }} · {{ version.creator?.name || 'Equipe' }}</p></article></div></section>
          <section class="panel min-w-0 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm shadow-td-card sm:p-6 [&_h2]:text-lg [&_h2]:font-semibold [&_h2]:leading-7 [&_h2]:text-td-ink flex flex-col gap-6 [&>.field-label]:mb-[-12px]"><h2>Eventos</h2><DataState v-if="!props.events.length" kind="empty" title="Nenhuma atividade registrada" /><ul v-else class="activity-list divide-y divide-td-border [&>li]:flex [&>li]:min-w-0 [&>li]:items-start [&>li]:gap-3 [&>li]:py-4 [&>li>div]:min-w-0 [&>li>div]:flex-1 [&_strong]:block [&_strong]:text-base [&_strong]:font-medium [&_strong]:text-td-ink [&>li>div>span]:text-sm [&>li>div>span]:leading-5 [&>li>div>span]:text-td-body"><li v-for="event in props.events" :key="event.id"><span class="activity-dot mt-2 inline-flex size-2 shrink-0 rounded-full bg-td-primary" aria-hidden="true" /><div><strong>{{ eventLabel(event.event) }}</strong><span>{{ dateTime(event.occurred_at) }}</span></div></li></ul></section>
        </main>
      </div>
    </div>
    <div class="sr-only" role="status" aria-live="polite">{{ copyState === 'copied' ? 'Link copiado.' : copyState === 'error' ? 'Não foi possível copiar o link.' : actionStatus }}</div>
  </AppShell>
<ConfirmModal :open="confirmation === 'resend'" title="Reenviar orçamento" message="Deseja reenviar este orçamento por e-mail ao cliente?" :busy="resendForm.processing" @cancel="confirmation = null" @confirm="confirmAction" />
  <ConfirmModal :open="confirmation === 'revoke'" title="Revogar link público" message="O link atual deixará de funcionar. Deseja continuar?" :busy="revokeForm.processing" @cancel="confirmation = null" @confirm="confirmAction" />
</template>
